import{_ as e,o as a,c as o,a6 as r}from"./chunks/framework.BrkgobfX.js";const p=JSON.parse('{"title":"状态码：5xx 服务端错误","description":"500–511 的触发条件，以及 502/503/504 在网关场景下的判定边界。","frontmatter":{"title":"状态码：5xx 服务端错误","description":"500–511 的触发条件，以及 502/503/504 在网关场景下的判定边界。","source":"https://daiw.org/manual/http11/status-5xx"},"headers":[],"relativePath":"manual/computer-programming/http11/status-5xx.md","filePath":"manual/computer-programming/http11/status-5xx.md"}'),n={name:"manual/computer-programming/http11/status-5xx.md"};function d(i,t,l,s,c,h){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="状态码-5xx-服务端错误" tabindex="-1">状态码：5xx 服务端错误 <a class="header-anchor" href="#状态码-5xx-服务端错误" aria-label="Permalink to &quot;状态码：5xx 服务端错误&quot;">​</a></h1><p>5xx 表示<strong>服务端知道自己出错或无法完成</strong>请求。除响应 <code>HEAD</code> 外 <strong>SHOULD</strong> 带解释体。</p><p>关键性质：客户端<strong>无需修改请求</strong>即可重试（前提是方法幂等）——这与 4xx 相反。</p><h2 id="_500-internal-server-error" tabindex="-1">500 Internal Server Error <a class="header-anchor" href="#_500-internal-server-error" aria-label="Permalink to &quot;500 Internal Server Error&quot;">​</a></h2><p>服务端遇到意外情况，无法完成。<strong>兜底码</strong>：所有未归类的服务端异常都落在这里。</p><ul><li>不应用它表达可归类的错误（<code>503</code> 过载、<code>504</code> 上游超时都有专码）。</li><li><strong>默认不可缓存</strong>。</li><li>生产中不得向外泄露堆栈——错误详情写日志，响应体只给相关 ID。</li></ul><h2 id="_501-not-implemented" tabindex="-1">501 Not Implemented <a class="header-anchor" href="#_501-not-implemented" aria-label="Permalink to &quot;501 Not Implemented&quot;">​</a></h2><p>服务端<strong>不支持该请求所需的功能</strong>，通常指方法本身未实现。</p><ul><li><strong>默认可缓存</strong>（在可缓存码列表中）——这点常被忽略。</li><li>与 <code>405</code> 的区别见<a href="/Front2Full/manual/computer-programming/http11/methods">方法</a>：<code>501</code> 是「这方法我不会」，<code>405</code> 是「这方法我会，但这资源不给用」。</li></ul><h2 id="_502-bad-gateway" tabindex="-1">502 Bad Gateway <a class="header-anchor" href="#_502-bad-gateway" aria-label="Permalink to &quot;502 Bad Gateway&quot;">​</a></h2><p><strong>网关/代理</strong>从上游收到<strong>无效响应</strong>。</p><p>判定边界：上游<strong>有响应但不合法</strong>（协议错误、连接被重置、TLS 握手失败）。若上游根本没在规定时间内响应，那是 <code>504</code>。</p><h2 id="_503-service-unavailable" tabindex="-1">503 Service Unavailable <a class="header-anchor" href="#_503-service-unavailable" aria-label="Permalink to &quot;503 Service Unavailable&quot;">​</a></h2><p>服务端<strong>当前</strong>无法处理，通常因过载或停机维护，且<strong>是暂时的</strong>。</p><ul><li><strong>SHOULD</strong> 带 <code>Retry-After</code>（<code>delay-seconds</code> 或 <code>HTTP-date</code>）。</li><li>默认不可缓存，但<strong>可</strong>被显式缓存指令覆盖。</li><li>语义明确暗示「稍后会恢复」——永久下线应用 <code>410</code> 或 <code>404</code>。</li><li>负载均衡健康检查失败、限流熔断打开时应返回此码，而非 <code>500</code>。</li></ul><h2 id="_504-gateway-timeout" tabindex="-1">504 Gateway Timeout <a class="header-anchor" href="#_504-gateway-timeout" aria-label="Permalink to &quot;504 Gateway Timeout&quot;">​</a></h2><p>网关/代理<strong>未能在时限内</strong>从上游获得响应。</p><p>与 <code>502</code> 的区别：<code>504</code> = 等不到；<code>502</code> = 等到了但不对。两者都发生在中间节点，不是源站自身的错误。</p><h2 id="_505-http-version-not-supported" tabindex="-1">505 HTTP Version Not Supported <a class="header-anchor" href="#_505-http-version-not-supported" aria-label="Permalink to &quot;505 HTTP Version Not Supported&quot;">​</a></h2><p>服务端不支持请求的<strong>主版本号</strong>。</p><ul><li>响应 <strong>SHOULD</strong> 说明支持哪些版本。</li><li>收到 <code>HTTP/1.9</code> 这类同主版本的高次版本号时<strong>不应</strong>返回此码——应按 <code>HTTP/1.1</code> 处理（见<a href="/Front2Full/manual/computer-programming/http11/request-line">请求行</a>）。</li></ul><h2 id="_506-variant-also-negotiates" tabindex="-1">506 Variant Also Negotiates <a class="header-anchor" href="#_506-variant-also-negotiates" aria-label="Permalink to &quot;506 Variant Also Negotiates&quot;">​</a></h2><p>RFC 2295（透明内容协商）。服务端配置错误：被选中的变体自身又是可协商资源，形成循环。极罕见。</p><h2 id="_507-508" tabindex="-1">507 / 508 <a class="header-anchor" href="#_507-508" aria-label="Permalink to &quot;507 / 508&quot;">​</a></h2><ul><li><code>507 Insufficient Storage</code>（RFC 4918）：WebDAV，存储空间不足以完成操作。</li><li><code>508 Loop Detected</code>（RFC 5842）：WebDAV，处理中检测到无限循环。</li></ul><h2 id="_510-not-extended" tabindex="-1">510 Not Extended <a class="header-anchor" href="#_510-not-extended" aria-label="Permalink to &quot;510 Not Extended&quot;">​</a></h2><p>RFC 2774（HTTP 扩展框架）。请求缺少服务端要求的扩展声明。该 RFC 为实验性，实际无部署。</p><h2 id="_511-network-authentication-required" tabindex="-1">511 Network Authentication Required <a class="header-anchor" href="#_511-network-authentication-required" aria-label="Permalink to &quot;511 Network Authentication Required&quot;">​</a></h2><p>RFC 6585。客户端需<strong>先通过网络接入认证</strong>（强制门户 / captive portal）才能上网。</p><p>关键约束：</p><ul><li><strong>必须由拦截代理生成</strong>，源服务器不应发送。</li><li>响应体应含指向登录页的链接，但<strong>不得</strong>用 <code>Location</code> 重定向——那会污染客户端对原目标 URI 的认知。</li><li>设计意图是让客户端（尤其是非浏览器程序）能<strong>机器可读地</strong>识别「我被强制门户拦了」，而不是把登录页误当成 API 响应。</li></ul><h2 id="_5xx-与重试" tabindex="-1">5xx 与重试 <a class="header-anchor" href="#_5xx-与重试" aria-label="Permalink to &quot;5xx 与重试&quot;">​</a></h2><table tabindex="0"><thead><tr><th>码</th><th>幂等方法可自动重试</th><th>建议退避</th></tr></thead><tbody><tr><td><code>500</code></td><td>⚠️ 谨慎（可能是确定性 bug，重试无用）</td><td>指数退避</td></tr><tr><td><code>502</code></td><td>✅</td><td>指数退避 + 抖动</td></tr><tr><td><code>503</code></td><td>✅</td><td><strong>遵循 <code>Retry-After</code></strong></td></tr><tr><td><code>504</code></td><td>⚠️ 上游可能已执行——非幂等禁止重试</td><td>指数退避</td></tr></tbody></table><p><code>504</code> 的隐患：网关超时不代表上游没执行。对 <code>POST</code> 而言，超时后重试可能造成重复副作用——必须用幂等键去重。</p><p>本部分结束。下一部分从<a href="/Front2Full/manual/computer-programming/http11/representation-fields">表示与内容字段</a>开始，逐组解析字段。</p>',35)])])}const g=e(n,[["render",d]]);export{p as __pageData,g as default};
